// Min-heap of the k list heads: O(N log k).
class MinHeap {
  constructor() {
    this.data = [];
  }
  push(entry) {
    this.data.push(entry);
    let i = this.data.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.data[p][0] <= this.data[i][0]) break;
      [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
      i = p;
    }
  }
  pop() {
    const top = this.data[0], last = this.data.pop();
    if (this.data.length) {
      this.data[0] = last;
      let i = 0;
      const n = this.data.length;
      while (true) {
        let s = i;
        const l = 2 * i + 1, r = 2 * i + 2;
        if (l < n && this.data[l][0] < this.data[s][0]) s = l;
        if (r < n && this.data[r][0] < this.data[s][0]) s = r;
        if (s === i) break;
        [this.data[i], this.data[s]] = [this.data[s], this.data[i]];
        i = s;
      }
    }
    return top;
  }
  get size() {
    return this.data.length;
  }
}

function mergeKLists(lists) {
  const heap = new MinHeap();
  for (let i = 0; i < lists.length; i++) {
    if (lists[i].length > 0) heap.push([lists[i][0], i, 0]);
  }
  const merged = [];
  while (heap.size > 0) {
    const [val, li, pos] = heap.pop();
    merged.push(val);
    if (pos + 1 < lists[li].length) heap.push([lists[li][pos + 1], li, pos + 1]);
  }
  return merged;
}

