#include <queue>
#include <vector>
using namespace std;
vector<int> mergeK(vector<vector<int>>&lists) {
    auto cmp=[](auto&a, auto&b) {
        return a[0]>b[0];
    };
    priority_queue<vector<int>, vector<vector<int>>, decltype(cmp)>h(cmp);
    for (int i=0; i<(int)lists.size(); i++)if (!lists[i].empty())h.push({lists[i][0], i, 0});
    vector<int>res;
    while (!h.empty()) {
        auto cur=h.top();
        h.pop();
        res.push_back(cur[0]);
        int i=cur[1], j=cur[2]+1;
        if (j<(int)lists[i].size())h.push({lists[i][j], i, j});
    }
    return res;
}
